 import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './AddQuestion.css';
import { postQuestion } from '../../services/api';
import HomeIcon from '../Common/HomeIcon';

function AddQuestion() {
  const [title, setTitle] = useState('');
  const [text, setText] = useState('');
  const [tags, setTags] = useState('');
  const [image, setImage] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(null);

  const navigate = useNavigate();

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    setImage(file);
    setPreviewUrl(file ? URL.createObjectURL(file) : null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!title || !text) {
      alert('Completează toate câmpurile!');
      return;
    }

    const formData = new FormData();
    formData.append('title', title);
    formData.append('text', text);
    tags.split(',').map(t => t.trim()).forEach(tag => formData.append('tagNames', tag));
    if (image) formData.append('image', image);

    try {
      await postQuestion(formData);
      alert('Întrebare adăugată!');
      navigate('/questions');
    } catch (err) {
      alert('Eroare: ' + err.message);
    }
  };

  return (
    <div className="add-question-container">
      <HomeIcon />
      <h2>Pune o întrebare</h2>
      <form onSubmit={handleSubmit}>
        <input type="text" placeholder="Titlu întrebare" value={title} onChange={(e) => setTitle(e.target.value)} />
        <textarea placeholder="Conținut întrebare" value={text} onChange={(e) => setText(e.target.value)} />
        <input type="text" placeholder="Etichete separate prin virgulă" value={tags} onChange={(e) => setTags(e.target.value)} />
        <input type="file" accept="image/*" onChange={handleImageChange} />

        {previewUrl && <img src={previewUrl} alt="preview" style={{ maxWidth: '100%', marginTop: '10px' }} />}

        <button type="submit">Trimite întrebare</button>
      </form>
    </div>
  );
}

export default AddQuestion;
